import {FIELD_MODES,fieldHours,withinField,rangeBounds,rainWindow,hourQuestion,hailSelection,hailEvidence} from './map-field-core.js';
import {mapIcon,weatherArt,lightningGlyph} from './map-visuals.js';
import {distanceText,rankShelters,directionsURL} from './nearby-tools.js';

// Owns local exploration, never starts an AI request or reads GPS automatically.
export function createFieldDesk(o){
 const {$,esc,L,map,api}=o,layer=L.layerGroup().addTo(map),rings=L.layerGroup().addTo(map),drafts=new Map(),cache=new Map();
 let key='',mode='temperature',place=null,radius=150,posts=[],reportState='loading',truncated=false,forecast=null,weatherState='loading',life=0,dead=false,open=false,places=[],shelterToken=0,refreshAt=0,expiryTimer;
 const current=()=>FIELD_MODES[mode],near=()=>place?(mode==='grandine'?hailSelection(posts,place,{radius,minutes:hailMinutes,includeEnded,sort:hailSort}):withinField(posts,place,radius)):[],time=t=>new Date(t).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit',timeZone:forecast?.timezone||undefined}),fmt=n=>Number.isFinite(n)?n.toLocaleString('it-IT',{maximumFractionDigits:1}):'—';
 const pending=new Map();let cacheGeneration=0;
 let shelterRadius=5,shelterCategory='car',hailMinutes=120,includeEnded=true,hailSort='distance',reportUpdatedAt=0;
 const clearCache=()=>{cacheGeneration++;cache.clear();pending.clear();};
 const cached=async(k,fn)=>{const r=cache.get(k);if(r&&Date.now()-r.at<120000)return r.value;if(pending.has(k))return pending.get(k);const generation=cacheGeneration,task=fn().then(value=>{if(generation===cacheGeneration){cache.set(k,{at:Date.now(),value});if(cache.size>35)cache.delete(cache.keys().next().value);}return value;}).finally(()=>{if(pending.get(k)===task)pending.delete(k);});pending.set(k,task);return task;};
 function sync(p,m){
  if(!p||dead)return;const next=[(Math.round(p.latitude*100)/100).toFixed(2),(Math.round(p.longitude*100)/100).toFixed(2),m].join(':');
  if(next===key&&Date.now()-refreshAt<120000){if(place?.name!==p.name||place.latitude!==p.latitude||place.longitude!==p.longitude){place={...p};render();draw();}return;}
  const changed=next!==key;key=next;place={...p};mode=m;refreshAt=Date.now();const token=++life;
  if(changed){posts=[];reportUpdatedAt=0;truncated=false;places=[];shelterToken++;forecast=null;}reportState='loading';weatherState='loading';render();draw();
  const lat=Math.round(place.latitude*100)/100,lon=Math.round(place.longitude*100)/100;
  cached('reports:'+key,()=>api('atlas/field-reports?'+new URLSearchParams({lat,lon,layer:mode,radius:150}))).then(d=>{if(dead||token!==life)return;posts=d.posts||[];reportUpdatedAt=cache.get('reports:'+key)?.at||Date.now();truncated=!!d.truncated;reportState='ok';render();draw();}).catch(()=>{if(dead||token!==life)return;reportState='error';render();draw();});
  const wxkey=lat+':'+lon;
  cached('weather:'+wxkey,()=>api('forecast?'+new URLSearchParams({lat,lon}))).then(d=>{if(dead||token!==life)return;forecast=d;weatherState='ok';render();}).catch(()=>{if(dead||token!==life)return;weatherState='error';render();});
 }

 function forecastMarkup(){
  if(weatherState==='loading')return '<p class="field-loading" role="status">Leggo le prossime 6 ore…</p>';
  const hours=fieldHours(forecast),config=current();
  if(weatherState==='error'||!hours.length)return '<p class="field-note">Andamento orario non disponibile. Riprova con Aggiorna dati.</p>';
  const value=h=>mode==='fulmini'?h.weather_code===null?'—':[95,96,99].includes(h.weather_code)?'Temporale':'Non indicato':fmt(h[config.field])+config.unit;
  const window=mode==='pioggia'&&!forecast._offline?rainWindow(hours):null;
  return '<div class="field-hours-heading"><span>PROSSIME ORE</span><small>Tocca per i dettagli ↗</small></div><div class="field-hour-grid">'+hours.map((h,i)=>'<button id="field-hour-'+i+'" data-field-hour="'+h.time+'" aria-label="Previsione delle '+time(h.time)+', '+esc(value(h))+'; apri tutti i dettagli"><time>'+time(h.time)+'</time><b>'+esc(value(h))+'</b><i style="--bar:'+bar(h)+'%" aria-hidden="true"></i></button>').join('')+'</div>'+(mode==='pioggia'?'<div class="field-window"><span>'+mapIcon('pioggia')+' PAUSA DALLA PIOGGIA</span><strong>'+(window?time(window.start)+' – '+time(window.end):'Non individuata')+'</strong><p>'+(forecast._offline?'Dati precedenti: aggiorna prima di confrontare le ore.':window?'Due ore con al massimo 0,2 mm e 30% di probabilità per ora nel modello. Non è una garanzia di asciutto.':'Nel campione non ci sono due ore future consecutive con pioggia e probabilità basse, oppure mancano dati.')+'</p></div>':'')+(mode==='fulmini'?'<p class="field-note">Temporali indicati dal modello, non singole scariche. Un temporale non indicato non esclude fulmini locali.</p>':'')+'<p class="field-source">Open-Meteo · '+esc(forecast.timezone||'UTC')+(forecast._offline?' · copia precedente del '+esc(new Date(forecast._loadedAt).toLocaleString('it-IT')):'')+'</p>';
 }
 function lightningGuide(){
  const hours=forecast?fieldHours(forecast):[],first=hours.find(h=>[95,96,99].includes(h.weather_code));
  const heading=forecast?forecast._offline?'Previsione precedente':first?'Temporali dalle '+time(first.time):'Controlla il cielo e le fonti':'Previsione non disponibile';
  return '<div class="lightning-guide"><div class="lightning-guide-title">'+lightningGlyph()+'<strong>'+heading+'</strong></div><p>Viola / M: temporale da modello. Ambra / C: osservazione della community, non verificata. I simboli non localizzano singole scariche.</p><p>Se senti tuoni, cerca un edificio al chiuso. Non aspettare una conferma dalla mappa.</p><a href="https://mappe.protezionecivile.it/it/mappe-e-dashboard-rischi/piattaforma-radar/" target="_blank" rel="noopener">Apri il radar ufficiale italiano · livello fulmini ↗</a><a href="https://rischi.protezionecivile.gov.it/it/meteo-idro/sei-preparato/" target="_blank" rel="noopener">Come proteggersi · Protezione Civile ↗</a></div>';
 }
 function render(){
  const slot=$('#mappa-field');if(!slot||dead||!place)return;
  const focusId=slot.contains(document.activeElement)?document.activeElement.id:null,scroll=slot.querySelector('.field-scroll')?.scrollTop||0;
  const config=current(),list=near(),closest=list.find(p=>!p.ended);
  if(mode==='grandine'){const count=$('[data-conteggio="grandine"]');if(count)count.textContent=reportState==='ok'?list.length+(truncated?'+':''):'—';}
  slot.classList.toggle('is-open',open);
  slot.innerHTML='<button class="field-mobile-handle" aria-expanded="'+open+'" id="field-expand"><span>'+mapIcon(mode)+' '+esc(config.name)+' · '+esc(place.name)+'</span><b>'+(open?'Chiudi −':'Esplora +')+'</b></button><div class="field-content"><div class="field-scroll"><div class="field-eyebrow">OSSERVATORIO LOCALE <span>'+mapIcon(mode)+'</span></div><div class="field-title-row"><h2>'+esc(place.name)+'</h2><div class="field-now">'+fmt(forecast?.current?.temperature_2m)+'<small>°C</small><span>'+(forecast?.current?.time?(forecast._offline?'precedente':'alle')+' '+esc(forecast.current.time.slice(11,16)):'dato locale')+'</span></div></div><p class="field-location">'+config.title+'</p>'+(mode==='grandine'?hailMarkup(list):forecastMarkup())+(mode==='fulmini'?lightningGuide():'')+'<p class="field-footnote">'+(mode==='grandine'?'Community · ultimi '+hailMinutes+' minuti · posizioni approssimate. Nessuna segnalazione non significa assenza di rischio.':'Osservazioni entro '+radius+' km · ultime 2 ore · non verificate.')+'</p></div><div class="field-actions"><button id="field-report" aria-label="Segnala '+config.name.toLowerCase()+'">'+mapIcon('plus')+' Segnala</button><button id="field-reports" aria-label="Osservazioni di '+config.name.toLowerCase()+' entro '+radius+' km">'+mapIcon('list')+' '+(reportState==='ok'?list.length+(truncated?'+':''):'—')+' report</button><button id="field-shelters" aria-label="Trova punti coperti entro 5 km">'+mapIcon('shelter')+' Ripari</button><button id="field-ai" class="field-ai" aria-label="Leggi '+config.name.toLowerCase()+' con Lente IA">'+mapIcon('ai')+' Lente IA</button></div></div>';
  $('#field-expand').onclick=()=>{open=!open;render();};
  slot.querySelectorAll('[data-field-radius]').forEach(b=>b.onclick=()=>{radius=Number(b.dataset.fieldRadius);render();draw();frame();});
  bindHailControls(slot);
  slot.querySelectorAll('[data-field-hour]').forEach(b=>b.onclick=()=>hourDetail(Number(b.dataset.fieldHour)));
  if($('#field-frame'))$('#field-frame').onclick=frame;
  $('#field-report').onclick=report;$('#field-reports').onclick=reportList;$('#field-shelters').onclick=()=>shelters(mode==='fulmini'?'people':'car');$('#field-ai').onclick=()=>o.askAI(config.question);
  if(mode==='fulmini')$('#field-shelters').setAttribute('aria-label','Trova edifici al chiuso entro 5 km');
  const body=slot.querySelector('.field-scroll');if(body)body.scrollTop=scroll;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});o.labelsChanged();
 }
 function hailMarkup(list){
  const evidence=hailEvidence(list,{state:reportState,updatedAt:reportUpdatedAt}),closest=list.find(p=>!p.ended);
  return `<section class="hail-desk" aria-label="Osservatorio grandine"><div class="hail-evidence is-${evidence.tone}" role="status"><span class="hail-kicker">DAL TERRITORIO</span><strong>${esc(evidence.title)}</strong><p>${esc(evidence.detail)}</p>${evidence.latest?'<p>Ultima osservazione alle '+time(evidence.latest)+(evidence.ended?' · '+evidence.ended+(evidence.ended===1?' cessata':' cessate'):'')+'</p>':''}</div><div class="hail-filter-heading">Distanza dalla zona scelta</div><div class="field-radius" role="group" aria-label="Raggio di ricerca grandine">${[25,50,100,150].map(n=>`<button id="field-radius-${n}" data-field-radius="${n}" aria-pressed="${radius===n}">${n} km</button>`).join('')}</div><div class="hail-filter-heading">Quando è stata osservata</div><div class="field-radius" role="group" aria-label="Età delle osservazioni">${[15,30,60,120].map(n=>`<button id="hail-minutes-${n}" data-hail-minutes="${n}" aria-pressed="${hailMinutes===n}">${n===120?'2 ore':n+' min'}</button>`).join('')}</div><button id="hail-ended" class="field-wide" aria-pressed="${includeEnded}">${includeEnded?'Incluse':'Escluse'} le osservazioni cessate</button><p class="field-note">${closest?'Più vicina non cessata: circa '+distanceText(closest.distance)+'. ':''}Distanze in linea d’aria, non tempi di arrivo.</p><div class="hail-source-actions"><button id="field-frame">Inquadra ${radius} km</button><button id="hail-radar">Apri radar pioggia</button></div><p class="field-note">Il radar mostra precipitazioni osservate; non misura la grandine. Il suo orario è separato da questi filtri.</p><div class="hail-updated"><span>${reportUpdatedAt?'Dati ricevuti alle '+time(reportUpdatedAt):'In attesa dei dati'}${truncated?' · campione parziale':''}</span><button id="hail-refresh" ${reportState==='loading'?'disabled':''}>Aggiorna</button></div></section>`;
 }
 function bindHailControls(slot){
  slot.querySelectorAll('[data-hail-minutes]').forEach(b=>b.onclick=()=>{hailMinutes=Number(b.dataset.hailMinutes);render();draw();});
  const ended=slot.querySelector('#hail-ended');if(ended)ended.onclick=()=>{includeEnded=!includeEnded;render();draw();};
  const radarButton=slot.querySelector('#hail-radar');if(radarButton)radarButton.onclick=()=>{open=false;render();o.openRadar();};
  const refreshButton=slot.querySelector('#hail-refresh');if(refreshButton)refreshButton.onclick=refresh;
 }
 function refresh(){clearCache();refreshAt=0;if(place)sync(place,mode);}
 function bar(h){const n=h[current().field];if(!Number.isFinite(n))return 0;if(mode==='temperature')return Math.max(5,Math.min(100,(n+10)*2));if(mode==='pioggia')return Math.min(100,n*12);if(mode==='vento')return Math.min(100,n*1.5);return [95,96,99].includes(n)?90:8;}
 function hourDetail(timestamp){
  const hours=fieldHours(forecast),index=hours.findIndex(h=>h.time===timestamp),h=hours[index];if(!h){o.panel('Orario non più disponibile','<p>La previsione è cambiata o quest’ora è trascorsa. Chiudi i dettagli e scegli un nuovo orario.</p>');return;}
  const date=new Date(h.time).toLocaleDateString('it-IT',{timeZone:forecast.timezone||'UTC',weekday:'long',day:'numeric',month:'short'});
  const metric=(name,value,unit)=>'<div><span>'+name+'</span><strong>'+fmt(value)+'<small> '+unit+'</small></strong></div>';
  o.panel('Ora per ora','<div class="field-hour-place">'+esc(place.name)+'</div><div class="field-hour-nav" role="group" aria-label="Scegli un orario">'+hours.map((p,i)=>'<button id="field-detail-'+i+'" data-hour-detail="'+p.time+'" aria-pressed="'+(i===index)+'">'+time(p.time)+'</button>').join('')+'</div><div class="field-hour-hero"><div><span>'+esc(date)+'</span><strong>'+time(h.time)+'</strong><small>'+esc(forecast.timezone||'UTC')+'</small></div>'+weatherArt(h.weather_code??-1,h.is_day??1)+'</div><div class="field-hour-metrics">'+metric('Temperatura',h.temperature_2m,'°C')+metric('Percepita',h.apparent_temperature,'°C')+metric('Vento medio',h.wind_speed_10m,'km/h')+metric('Raffica massima¹',h.wind_gusts_10m,'km/h')+metric('Precipitazioni¹',h.precipitation,'mm')+metric('Probabilità¹',h.precipitation_probability,'%')+'</div><p class="field-hour-condition">'+(h.weather_code===null?'Condizione meteo non disponibile.':[95,96,99].includes(h.weather_code)?'Temporale previsto dal modello. Non è una scarica rilevata.':'Nessun codice temporale in questa previsione. Non esclude fenomeni locali.')+'</p><button id="field-hour-ai" class="mappa-primary">'+mapIcon('ai')+' Spiega quest’ora con Lente IA</button><p class="field-source">¹ Totale precipitazioni, probabilità e raffica massima nell’intervallo '+time(h.time-3600000)+'–'+time(h.time)+'. Gli altri valori si riferiscono alle '+time(h.time)+'.</p><p class="field-source">Fonte: Open-Meteo · previsione'+(forecast._offline?' · copia precedente del '+esc(new Date(forecast._loadedAt).toLocaleString('it-IT')):'')+'. La mappa e il radar mantengono i propri orari.</p>');
  document.querySelectorAll('[data-hour-detail]').forEach(b=>b.onclick=()=>{const at=Number(b.dataset.hourDetail);hourDetail(at);document.querySelector('[data-hour-detail="'+at+'"]')?.focus({preventScroll:true});});
  $('#field-hour-ai').onclick=()=>o.askAI((forecast._offline?'Dati precedenti, non aggiornati. ':'')+hourQuestion(h,forecast.timezone||'UTC'));
 }
 function frame(){open=false;render();map.fitBounds(rangeBounds(place,radius),{paddingTopLeft:matchMedia('(max-width:920px)').matches?[25,215]:[315,170],paddingBottomRight:[90,165],animate:!matchMedia('(prefers-reduced-motion:reduce)').matches,maxZoom:9});}
 function draw(){
  layer.clearLayers();rings.clearLayers();if(!place||dead)return;
  if(mode==='grandine')for(const km of [50,100,150].filter(n=>n<=radius).concat([25].filter(n=>radius===n))){
   L.circle([place.latitude,place.longitude],{radius:km*1000,color:'#ffad80',weight:km===radius?1.5:1,opacity:km===radius?.7:.35,dashArray:km===radius?'3 6':'2 10',fillColor:'#fc995e',fillOpacity:km===radius?.035:0,interactive:false}).addTo(rings);
   const b=rangeBounds(place,km);L.marker([b[1][0],place.longitude],{interactive:false,keyboard:false,icon:L.divIcon({className:'field-range-label',html:km+' km',iconSize:[60,22],iconAnchor:[30,11]})}).addTo(rings);
  }
  for(const p of near()){
   const pin=L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:(mode==='fulmini'?'lightning-pin is-report':'field-report-pin')+(p.ended?' is-ended':''),html:mode==='fulmini'?lightningGlyph('report'):mapIcon(mode)+'<i></i>',iconSize:mode==='fulmini'?[44,48]:[36,40],iconAnchor:mode==='fulmini'?[22,40]:[18,32]}),title:p.city+' · osservazione '+current().name,alt:p.city+', segnalazione '+current().name});pin.on('click',()=>reportDetail(p));layer.addLayer(pin);pin.getElement()?.setAttribute('aria-label',p.city+', segnalazione '+current().name);
  }
  for(const p of places){const pin=L.marker([p.latitude,p.longitude],{icon:L.divIcon({className:'field-shelter-pin',html:mapIcon('shelter'),iconSize:[40,40],iconAnchor:[20,20]}),title:p.name,alt:p.name+', punto coperto da verificare'});pin.on('click',()=>shelterDetail(p));layer.addLayer(pin);pin.getElement()?.setAttribute('aria-label',p.name+', punto coperto da verificare');}
 }
 function reportList(){
  const list=near(),minutes=mode==='grandine'?hailMinutes:120;
  o.panel('Osservazioni · '+current().name,`<p>Entro ${radius} km da ${esc(place.name)} · ultimi ${minutes} minuti · posizioni approssimate</p>${mode==='grandine'?'<div class="field-radius" role="group" aria-label="Ordina osservazioni"><button id="hail-sort-distance" data-hail-sort="distance" aria-pressed="'+(hailSort==='distance')+'">Più vicine</button><button id="hail-sort-recent" data-hail-sort="recent" aria-pressed="'+(hailSort==='recent')+'">Più recenti</button></div>':''}<div class="field-report-list">${reportState==='loading'?'<p role="status">Caricamento delle osservazioni…</p>':reportState==='error'?'<p role="status">Impossibile aggiornare le segnalazioni. Torna alla mappa e riprova.</p>':list.map((p,i)=>`<button data-field-post="${i}"><span><b>${esc(p.city)}</b><small>${Math.max(0,Math.floor((Date.now()-(p.observed??p.created))/60000))} min fa · alle ${time(p.observed??p.created)} · ${p.ended?'cessata per l’autore':'non verificata'}</small></span><strong>~${distanceText(p.distance)}</strong></button>`).join('')||'<p>Nessuna osservazione nei filtri. Non è una conferma di cielo sereno.</p>'}</div>${truncated?'<p>Campione parziale: ci sono altre osservazioni. Il conteggio non rappresenta tutti i report.</p>':''}<button class="mappa-primary" id="field-list-report">Aggiungi la tua osservazione</button>`);
  $('#field-list-report').onclick=report;
  document.querySelectorAll('[data-field-post]').forEach(b=>b.onclick=()=>reportDetail(list[+b.dataset.fieldPost]));
  document.querySelectorAll('[data-hail-sort]').forEach(b=>b.onclick=()=>{const id=b.id;hailSort=b.dataset.hailSort;reportList();document.getElementById(id)?.focus({preventScroll:true});});
 }
 function reportDetail(p){
  o.panel(p.city+' · '+current().name,`<p class="field-note">Community · non verificata · ${new Date(p.observed).toLocaleString('it-IT')}</p><p>${esc(p.text)}</p><p>Circa ${distanceText(p.distance)} dalla zona selezionata. Posizione arrotondata, non distanza da un fronte meteo.</p>${p.ended?'<p>L’autore ha indicato che il fenomeno è cessato dal suo punto di osservazione.</p>':''}<button id="field-post-community">Apri la community ↗</button>`);$('#field-post-community').onclick=()=>o.openPlace({...place,name:p.city,latitude:p.latitude,longitude:p.longitude},'community');
 }
 function report(){
  if(!o.get().me)return o.login();const p={...place},config=current(),draftKey=key,d=drafts.get(draftKey)||{id:crypto.randomUUID(),text:'',city:p.source==='gps'?'':p.name};drafts.set(draftKey,d);
  o.modal('Segnala '+config.name.toLowerCase(),`<p>Racconta solo ciò che stai osservando da un posto protetto.</p><label class="field"><span>Comune della zona scelta</span><input id="field-report-city" ${p.source==='gps'?'':'readonly'} required maxlength="80" value="${esc(d.city)}"></label><label class="field"><span>La tua osservazione</span><textarea id="field-report-text" required maxlength="1000" placeholder="Es. Raffiche forti sul lungomare">${esc(d.text)}</textarea></label><label class="scanner-consent"><input id="field-report-consent" type="checkbox" required> Confermo di aver osservato il fenomeno adesso nella zona scelta. Pubblica il testo e la posizione approssimata a circa 1 km per 2 ore.</label><p>Centro selezionato: ${esc(p.name)}. Per un’altra zona, chiudi e cercala sulla mappa. Non inviamo questo report all’IA.</p>`,async()=>{
   if(!$('#field-report-consent').checked)return false;
   await api('posts',{id:d.id,kind:config.kind,text:d.text,city:d.city,rapid:true,mapPoint:{latitude:p.latitude,longitude:p.longitude,consent:true}});
   drafts.delete(draftKey);clearCache();key='';sync(place,mode);o.toast('Osservazione pubblicata nella mappa e nella community per 2 ore.');return true;
  });$('#confirm-dialog').textContent='Pubblica osservazione';$('#field-report-text').oninput=e=>d.text=e.target.value;$('#field-report-city').oninput=e=>d.city=e.target.value;
 }
 async function shelters(category,retry=false){
  const p={...place},token=++shelterToken,lat=Math.round(p.latitude*100)/100,lon=Math.round(p.longitude*100)/100;
  shelterCategory=category;places=[];draw();
  const cacheKey='shelters:'+lat+':'+lon+':'+category;if(retry)cache.delete(cacheKey);
  const external='<a class="field-external" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?'+esc(new URLSearchParams({api:'1',query:(category==='car'?'parcheggi coperti vicino a ':'biblioteche e edifici pubblici vicino a ')+lat+','+lon}))+'">Cerca anche su Google Maps ↗</a>';
  const safety=mode==='fulmini'?'Con tuoni o fulmini cerca un edificio al chiuso. Una tettoia o un albero non offrono protezione.': 'Non raggiungere garage interrati o sottopassi se c’è rischio di allagamento. Non uscire durante la grandinata per salvare l’auto.';
  const controls=()=>'<div class="shelter-tabs" role="group" aria-label="Tipo di luogo"><button data-shelter-type="car" aria-pressed="'+(category==='car')+'">'+mapIcon('shelter')+' Auto al coperto</button><button data-shelter-type="people" aria-pressed="'+(category==='people')+'">'+mapIcon('shelter')+' Edifici al chiuso</button></div>';
  const bindTypes=()=>document.querySelectorAll('[data-shelter-type]').forEach(b=>b.onclick=()=>shelters(b.dataset.shelterType));
  o.panel('Ripari · '+p.name,controls()+'<div class="shelter-searching" role="status">Cerco nella zona, fino a 5 km…</div><p>Puoi già aprire la ricerca alternativa. Usiamo il centro selezionato, arrotondato.</p>'+external);bindTypes();const panelToken=o.panelToken();
  let d;
  try{d=await cached(cacheKey,()=>api('pulse/nearby?'+new URLSearchParams({lat,lon,category})));if(d.sourceError)cache.delete(cacheKey);}
  catch(e){d={places:[],sourceError:e.message||'Ricerca temporaneamente non disponibile.'};}
  if(dead||token!==shelterToken||panelToken!==o.panelToken())return;
  const renderResults=()=>{
   places=rankShelters(d.places||[],p,'all',shelterRadius).filter(x=>x.type===category||x.type==='unknown');draw();
   o.panel('Ripari · '+p.name,controls()+`<div class="shelter-result-heading"><strong>${d.sourceError&&!places.length?'—':places.length}</strong><span>luoghi nel campione<br>entro ${shelterRadius} km</span></div><div class="field-radius" role="group" aria-label="Distanza ripari">${[1,3,5].map(k=>`<button data-shelter-radius="${k}" aria-pressed="${k===shelterRadius}">${k} km</button>`).join('')}</div><p class="field-note">Dal centro selezionato · distanze in linea d’aria · posti liberi sconosciuti</p>${d.sourceError?'<p role="status" class="field-warning">'+esc(d.sourceError)+'</p>':''}<div class="field-report-list shelter-results">${places.map((x,i)=>`<button data-shelter="${i}"><span class="shelter-list-icon" aria-hidden="true">${mapIcon('shelter')}</span><span><b>${esc(x.name)}</b><small>${x.type==='unknown'?'Community · copertura da verificare':x.type==='people'?'Edificio al chiuso · OSM':'Parcheggio coperto · OSM'}</small></span><strong>${distanceText(x.distance)}<small>Dettagli ↗</small></strong></button>`).join('')||'<p>Nessun luogo trovato in questo raggio. Prova 5 km o la ricerca alternativa: il campione può essere incompleto.</p>'}</div><div class="shelter-bottom-actions"><button id="shelter-frame" ${places.length?'':'disabled'}>Mostra sulla mappa</button><button id="shelter-retry">Riprova ricerca</button></div>${external}<p class="shelter-safety">${safety}</p><p class="field-note">Luoghi cartografati, non rifugi certificati. Verifica copertura, accesso e apertura. Non conosciamo la sicurezza del percorso.</p>${d.osmAt?'<p class="field-source">Dati OSM: '+esc(new Date(d.osmAt).toLocaleString('it-IT'))+'</p>':''}${d.truncated?'<p>Risultati community parziali.</p>':''}`);
   bindTypes();document.querySelectorAll('[data-shelter-radius]').forEach(b=>b.onclick=()=>{shelterRadius=Number(b.dataset.shelterRadius);renderResults();});
   document.querySelectorAll('[data-shelter]').forEach(b=>b.onclick=()=>shelterDetail(places[+b.dataset.shelter],renderResults));
   $('#shelter-retry').onclick=()=>shelters(category,true);
   $('#shelter-frame').onclick=()=>map.fitBounds([[p.latitude,p.longitude],...places.map(x=>[x.latitude,x.longitude])],{paddingTopLeft:matchMedia('(max-width:920px)').matches?[35,190]:[370,170],paddingBottomRight:[90,170],maxZoom:15,animate:false});
  };renderResults();
 }
 function shelterDetail(p,back=null){
  map.setView([p.latitude,p.longitude],14,{animate:false});o.panel(p.name,`<p>${mapIcon('shelter')} ${esc(p.source)} · ${distanceText(p.distance)} in linea d’aria</p><p>${esc(p.details||'Dettagli non presenti nella fonte.')}</p><dl class="field-shelter-details"><dt>Orari dichiarati</dt><dd>${esc(p.openingHours||'Non disponibili')}</dd><dt>Accesso / costo</dt><dd>${esc(({unknown:'Da verificare',yes:'Accesso pubblico indicato',permissive:'Accesso consentito indicato',customers:'Riservato ai clienti',destination:'Accesso a destinazione'})[p.access]||p.access||'Da verificare')} · ${esc(p.fee||'Da verificare')}</dd><dt>Posti liberi</dt><dd>Non disponibili</dd></dl><p>Verifica accesso e copertura prima di partire. Le indicazioni stradali non considerano necessariamente allagamenti o pericoli.</p><a class="field-external" target="_blank" rel="noopener" href="${esc(directionsURL(p,p.type==='people'?'people':'car'))}">Indicazioni con Google Maps ↗</a>${p.sourceURL?`<a class="field-external" href="${esc(p.sourceURL)}" target="_blank" rel="noopener">Scheda OpenStreetMap ↗</a>`:''}`);
  const body=$('#mappa-pannello-corpo');if(body){const button=document.createElement('button');button.className='field-wide';button.textContent='← Torna ai ripari';button.onclick=()=>back?back():shelters(shelterCategory);body.prepend(button);}
 }
 expiryTimer=setInterval(()=>{if(!dead&&!document.hidden){render();draw();}},60000);
 return {sync,count:()=>reportState==='ok'?near().length:null,summary:()=>mode==='grandine'?('Grandine negli ultimi '+hailMinutes+' minuti entro '+radius+' km da '+place?.name+': '+(reportState==='ok'?near().filter(p=>!p.ended).length+' osservazioni non verificate nel campione'+(Date.now()-reportUpdatedAt>=300000?' (dati precedenti da aggiornare)':''):'dati non disponibili')+'. Distanze geografiche, nessuna traiettoria o tempo di impatto disponibile. Ripari ricercabili separatamente entro 5 km, nessuna disponibilità garantita.'):'',refresh,dispose(){dead=true;life++;shelterToken++;clearInterval(expiryTimer);layer.remove();rings.remove();},close(){if(open){open=false;render();}}};
}
